{
  "criteria": {
    "comprehension": {
      "band": "B",
      "evidence": "The candidate understood the questions about her role and project. The response to the reduced-budget scenario, « j'aurais priorisé les régions avec le plus de demandes », also shows that she understood the hypothetical. That response was typed, however, and the exchange offers limited evidence of comprehension of linguistically complex speech."
    },
    "fluency": {
      "band": "B",
      "evidence": "After an initial « Euh », the spoken answers continue without a visible breakdown. They are brief, so they do not establish the sustained, detailed delivery expected at C. The typed final answer cannot be used to assess spoken fluency."
    },
    "grammar": {
      "band": "B",
      "evidence": "The spoken answers use several workable sentence patterns, but « les dossiers devient » and « les régions voulait » show agreement errors. The conditional error in « Si le budget aurait été réduit » is in a typed answer, so it should not be treated as evidence of grammar under speaking pressure."
    },
    "vocabulary": {
      "band": "B",
      "evidence": "Terms such as « consultations avec les provinces », « notes pour la sous-ministre » and « processus de demande de subventions » fit the workplace topic. The candidate does not yet use enough precise language to explain the project's trade-offs or results in depth."
    },
    "task": {
      "band": "B",
      "evidence": "The candidate identifies her role, a project challenge and an action: « j'ai organisé des ateliers pour trouver un compromis ». She does not explain the compromise reached or the project's results. The final answer proposes a budget response, but it is typed and gives little reflection on why that approach would work."
    }
  },
  "fixes": [
    {
      "criterion": "task",
      "subSkill": "specific-detail",
      "advice": "After describing an action, add the decision reached, your own contribution and the result. For the budget scenario, explain the reason for your priorities and what would be delayed.",
      "evidence": "« j'ai organisé des ateliers pour trouver un compromis » identifies an action but not its outcome; « reporté le reste à l'année suivante » does not specify what would be deferred."
    },
    {
      "criterion": "grammar",
      "subSkill": "verb-tense-and-mood",
      "advice": "Practise counterfactual answers with the pattern « si » plus the pluperfect, followed by the past conditional. The example available here was typed, so check that you can also produce the pattern aloud.",
      "evidence": "« Si le budget aurait été réduit » uses the conditional where the pluperfect is needed."
    },
    {
      "criterion": "grammar",
      "subSkill": "agreement",
      "advice": "Before moving on from a clause, check whether its verb agrees with a plural subject, especially when other words separate the two.",
      "evidence": "« les dossiers devient » and « les régions voulait » both pair a plural subject with a singular verb."
    }
  ],
  "missingWords": [
    {
      "word": "besoins régionaux",
      "turn": 3,
      "excerpt": "les régions voulait garder leurs propres formulaires",
      "example": "Les régions voulaient garder leurs propres formulaires; j'ai donc organisé des ateliers pour tenir compte des besoins régionaux."
    },
    {
      "word": "points de divergence",
      "turn": 3,
      "excerpt": "j'ai organisé des ateliers pour trouver un compromis",
      "example": "J'ai organisé des ateliers pour cerner les points de divergence et trouver un compromis."
    },
    {
      "word": "marge de manœuvre",
      "turn": 5,
      "excerpt": "Si le budget aurait été réduit",
      "example": "Si le budget avait été réduit de moitié, notre marge de manœuvre aurait été plus limitée."
    },
    {
      "word": "critères de priorisation",
      "turn": 5,
      "excerpt": "j'aurais priorisé les régions avec le plus de demandes",
      "example": "J'aurais établi des critères de priorisation fondés sur le volume des demandes dans chaque région."
    },
    {
      "word": "échéancier",
      "turn": 5,
      "excerpt": "reporté le reste à l'année suivante",
      "example": "J'aurais revu l'échéancier et reporté le reste à l'année suivante."
    }
  ],
  "errors": [
    {
      "turn": 1,
      "excerpt": "devient",
      "correction": "deviennent",
      "rule": "The verb must agree in number with its plural subject, « les dossiers »."
    },
    {
      "turn": 3,
      "excerpt": "voulait",
      "correction": "voulaient",
      "rule": "The verb must agree in number with its plural subject, « les régions »."
    },
    {
      "turn": 5,
      "excerpt": "Si le budget aurait été réduit",
      "correction": "Si le budget avait été réduit",
      "rule": "In a past counterfactual condition, use the pluperfect after « si », not the past conditional."
    }
  ]
}
